# ----------------------------------------------------------------------
# 既知の銘柄・口座（MF PDF 取込済みを模したもの）
# ----------------------------------------------------------------------

def universe(
    *specs: tuple[str, str | None, int],
    accounts: tuple[str, ...] = ("架空証券",),
) -> KnownUniverse:
    """(銘柄名, コード, divisor) から KnownUniverse を組む。"""
    secs = tuple(
        KnownSecurity(
            id=i + 1,
            code=code,
            name=name,
            name_key=make_name_key(name),
            price_unit_divisor=divisor,
        )
        for i, (name, code, divisor) in enumerate(specs)
    )
    return KnownUniverse(
        securities=secs,
        by_code={s.code: s for s in secs if s.code},
        by_name_key={s.name_key: s for s in secs},
        by_alias={},
        known_codes=frozenset(s.code for s in secs if s.code),
        account_names=frozenset(accounts),
    )


STOCK_UNIVERSE = universe(("架空商事", "1234", 1), ("架空製作所", "5678", 1))
FUND_UNIVERSE = universe(("架空インデックスファンド", None, 10000))


