def csv_bytes(text: str, encoding: str = "utf-8") -> bytes:
    return text.encode(encoding)


def xlsx_bytes(rows: list[list[object]], sheet_name: str = "取引履歴") -> bytes:
    """openpyxl で xlsx を組み立てる。未導入なら pytest.skip 用に None を返す。"""
    try:
        import openpyxl
    except ImportError:  # pragma: no cover
        return b""
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = sheet_name
    for row in rows:
        ws.append(row)
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def fake_xls_bytes() -> bytes:
    """旧 Excel(.xls) の magic だけ持つダミー。案内が出ることの確認用。"""
    return b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1" + b"\x00" * 64


def fake_zip_bytes() -> bytes:
    """xlsx ではない zip（docx 等）。xlsx と誤判定しないことの確認用。"""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w") as zf:
        zf.writestr("word/document.xml", "<x/>")
    return buf.getvalue()
